from decimal import Decimal


def _value(mapping: dict | None, field: str) -> object:
    if mapping is None:
        return ""
    value = mapping.get(field, "")
    return "" if value is None else value


def _text(mapping: dict | None, field: str) -> str:
    return str(_value(mapping, field))


def _number(value: object) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _numeric_equal(value: object, expected: object) -> bool:
    return _number(value) == _number(expected)


def _date_equal(value: object, expected: str) -> bool:
    return _text({"_": value}, "_") == expected


def _date_greater_equal(value: object, other: str) -> bool:
    left = _text({"_": value}, "_")
    if left == "00000000" or other == "00000000":
        return False
    return left >= other


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []
    old_image = old if event == "UPDATE" else {}

    def failure(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    stat_cd = _text(record, "STAT_CD")
    amount = _value(record, "AMT")
    lost_reason = _text(record, "LOST_RSN")
    close_date = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (_number(amount) >= Decimal("0")):
            failure("E3001", "Amount negative")

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and _number(amount) == Decimal("0"):
            failure("E3002", "Won opportunity requires amount")

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "L" and lost_reason == "":
            failure("E3003", "Lost reason required")

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and _date_equal(close_date, "00000000"):
            failure("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _text(old_image, "STAT_CD")
        if old_stat_cd == "W" and stat_cd != "W":
            failure("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage_consistent = (
            (stat_cd == "P" and _numeric_equal(stage_pct, 10))
            or (stat_cd == "Q" and _numeric_equal(stage_pct, 25))
            or (stat_cd == "N" and _numeric_equal(stage_pct, 60))
            or (stat_cd == "W" and _numeric_equal(stage_pct, 100))
            or (stat_cd == "L" and _numeric_equal(stage_pct, 0))
        )
        if not stage_consistent:
            failure("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        if not (
            _date_equal(close_date, "00000000")
            or _date_greater_equal(close_date, today)
        ):
            failure("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
